import * as tt from "thinkthen";

// a batch you can cancel: abort() stops the requests
const inbox = ["Can we move Thursday's call?",
    "Checkout is down and nobody can pay."];
const stop = new AbortController();
const urgent = await tt.rank("Is this urgent?",
    inbox, { top: 1, signal: stop.signal });
// the outage is the most urgent
console.log(urgent[0].record);
